  const lut = new Float32Array(256);
  for (let q = 0; q < 128; q++) {
    const mag = Math.exp(lnMin * (1 - q / 127));
    lut[q] = mag;
    lut[q | 128] = -mag;
  }
  return { n, nnz, colPtr, rowIdx, code, lut };
}

